def require(ok, message="qualification failed"):
    if not ok:
        raise ValueError(message)

def canonical(value):
    return (json.dumps(value, sort_keys=True, ensure_ascii=False,
                       separators=(",", ":"), allow_nan=False) + "\n").encode("utf-8")

def digest(raw):
    return hashlib.sha256(raw).hexdigest()

def git_blob(raw):
    return hashlib.sha1(b"blob " + str(len(raw)).encode() + b"\0" + raw).hexdigest()

def exact_json(raw):
    return json.loads(raw.decode("utf-8"),
        parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))

def at(value, path):
    for key in path:
        value = value[key]
    return value

def qualified_projection(value):
    """Keep every non-ball leaf, empty container and array position.
    Timing is the sole operational scalar excluded from this second identity.
    Full original byte and Git identities are checked independently.
    """
    if isinstance(value, list):
        return [qualified_projection(item) for item in value]
    if isinstance(value, dict):
        if set(value) == {"ball"} and isinstance(value["ball"], str):
            return None
        return {key: qualified_projection(item) for key, item in value.items()
                if key != "actual_mathematical_wall_seconds"}
    if isinstance(value, str) and value.startswith("[") and "+/-" in value:
        return None
    return value

def safe_path(root, relative):
    require(isinstance(relative, str) and relative and not Path(relative).is_absolute()
            and ".." not in Path(relative).parts, "safe complete relative path")
    path = (root / relative).resolve()
    require(path.is_relative_to(root), "complete path escaped repository")
    return path

def check_file(root, spec):
    require(isinstance(spec, dict) and set(spec) ==
            {"role", "path", "bytes", "sha256", "git_blob_sha"}, "five-key file identity")
    require(isinstance(spec["role"], str) and len(spec["role"]) <= 64
            and isinstance(spec["path"], str) and len(spec["path"]) <= 256
            and type(spec["bytes"]) is int and 0 < spec["bytes"] < 100000
            and re.fullmatch("[0-9a-f]{64}", spec["sha256"])
            and re.fullmatch("[0-9a-f]{40}", spec["git_blob_sha"]),
            "bounded complete file identity")
    raw = safe_path(root, spec["path"]).read_bytes()
    require(len(raw) == spec["bytes"] and digest(raw) == spec["sha256"]
            and git_blob(raw) == spec["git_blob_sha"],
            "complete immutable file differs: " + spec["role"])
    raw.decode("utf-8")
    return raw

def scalar_records(value):
    if isinstance(value, dict):
        if set(value) == {"ball"} and isinstance(value["ball"], str):
            return 1
        return sum(scalar_records(item) for item in value.values())
    if isinstance(value, list):
        return sum(scalar_records(item) for item in value)
    return 0

def complete_gates(old, count):
    require(isinstance(old["gates"], list) and len(old["gates"]) == count
            and all(set(gate) == {"name", "passed"} and gate["passed"] is True
                    and isinstance(gate["name"], str) for gate in old["gates"]),
            "whole original gate list")

def complete_new_graph_count(old, count):
    require(old["complete"] is True and old["proved"] is True
            and old["actual_returncode"] == 0 and old["failure"] is None
            and old["stage"] == "complete" and old["current_target"] is None,
            "complete original scientific process")
    require(set(old["saved_record_counts"]) == set(old["complete_new_graphs"])
            and sum(old["saved_record_counts"].values()) == count
            and all(scalar_records(old["complete_new_graphs"][key]["new_records"]) == number
                    for key, number in old["saved_record_counts"].items()),
            "all original saved new graphs and records")
    require(old["actual_progress"]["new_records_saved"] == count
            and old["actual_progress"]["old_scientific_calls"] == 0
            and old["actual_progress"]["old_targets_recomputed"] == 0,
            "original process counts and no old target rerun")

def read_only_admission(repo, manifest_file, manifest_sha):
    root = Path(repo).resolve()
    manifest_raw = Path(manifest_file).read_bytes()
    require(0 < len(manifest_raw) < 100000 and digest(manifest_raw) == manifest_sha,
            "whole manifest CLI identity")
    manifest = exact_json(manifest_raw)
    expected_roles = [spec["role"] for spec in EXPECTED_OLD_FILES] + [
        "support", "finishing", "science", "schema",
        "proof_WSJ", "proof_WCPR", "worker", "rules"]
    specs = manifest["files"]
    require(isinstance(specs, list) and len(specs) == 20
            and [item["role"] for item in specs] == expected_roles
            and len({item["path"] for item in specs}) == 20,
            "twenty current complete files in exact order")
    require(manifest["repository"] == PUBLIC_REPOSITORY
            and manifest["problem_id"] == PROBLEM_ID
            and manifest.get("historical_inputs", []) == []
            and manifest["parameters"] == PARAMETERS,
            "same selected problem, zero history and complete parameters")
    files = {item["role"]: item for item in specs}
    for spec in EXPECTED_OLD_FILES:
        require(files[spec["role"]] == spec, "original immutable pin differs")
    for role, spec in FIXED_NEW_FILES.items():
        require(files[role] == spec, "reviewed new library, shape, proof or worker differs")
