def copy_complete_WBF_angular_packet(wbf, source_identity, wgs_main, wgs_copies):
    """Pure JSON projection AFTER the owner's complete immutable admission.
    No new arithmetic, parser for ball values, or producer invocation.
    The owner must verify the original bytes and complete packet_binding.
    """
    import copy
    def need(ok, message):
        if not ok:
            raise ValueError(message)
    def records(value, count, label):
        need(isinstance(value, list) and len(value) == count, label + " length")
        need(all(isinstance(r, dict) and set(r) == {"ball"}
                 and isinstance(r["ball"], str) for r in value),
             label + " complete original records")
        return copy.deepcopy(value)
    names = (
        "complete_new_sharp_flow_conclusion",
        "complete_new_sharp_phase_conclusion",
        "complete_new_sharp_relative_bulk_conclusion",
        "complete_new_sharp_transport_relative_conclusion",
        "complete_new_sharp_relative_omega_conclusion")
    need(set(source_identity) == {"role", "path", "bytes", "sha256", "git_blob_sha"}
         and type(source_identity["bytes"]) is int and source_identity["bytes"] > 0
         and isinstance(source_identity["path"], str)
         and len(source_identity["sha256"]) == 64
         and len(source_identity["git_blob_sha"]) == 40,
         "one complete admitted five-key scientific identity")
    need(wbf["kind"] == "complete_sharp_Bernstein_integrated_finite_flow_bounds"
         and wbf["problem_id"] == "same_selected_sharp_Bernstein_flow15_relative_omega14_v1"
         and wbf["complete"] is True and wbf["proved"] is True
         and wbf["actual_returncode"] == 0 and wbf["failure"] is None
         and wbf["stage"] == "complete" and wbf["current_target"] is None
         and wbf["completed_targets"] == list(names),
         "one complete WBF mathematical receipt")
    need(wbf["scientific_modules"] ==
         {"science": "7534760ac0e6867425c773598438c7909a502b6d84e05cc5c7c430637eee2ac7"}
         and wbf["saved_record_counts"] == dict(zip(names, (14, 14, 14, 27, 14)))
         and wbf["actual_progress"]["new_records_saved"] == 83
         and wbf["actual_progress"]["old_scientific_calls"] == 0
         and wbf["actual_progress"]["old_targets_recomputed"] == 0,
         "the frozen complete 83-target science")
    pars, scope = wbf["parameters"], wbf["retained_scope"]
    need(pars["strict_interval"] == ["0", "76285779072683/320000000000000"]
         and pars["physical_period"] == "pi/2"
         and pars["actual_drift_label_bandwidth"] == 192
         and pars["actual_drift_physical_bandwidth"] == 768
         and pars["maximum_relative_omega_angular_order"] == 14
         and scope["all_shorter_both_orientations_both_characteristics_and_drift"] is True
         and scope["original_first_positive_comparison_budget_bounds_exp_integral_D"] is True
         and scope["original_F1_P1_K1_and_all_cut_records_read_only"] is True,
         "same full angular and positive-comparison qualification")
    graphs = wbf["complete_new_graphs"]
    need(set(graphs) == set(names) and all(
        graphs[n]["complete"] is True
        and graphs[n]["ordinary_physical_angular_derivatives"] is True
        and graphs[n]["strict_interval"] == pars["strict_interval"]
        and graphs[n]["complete_original_cut_and_all_shorter_flow"] is True
        and graphs[n]["sharp_Bernstein_integrated_majorant"] is True
        for n in names), "all five full graph scopes")
    old = wbf["copied_original_scalar_records"]
    need(old["flow_1"] == wgs_copies["copied_original_scalar_records"]["flow_1"]
         and old["phase_1"] == wgs_main["complete_higher_flow_and_cut_conclusion"][
            "complete_strict_phase_angular_orders_1_through_15"][0]
         and old["strict_phase_lower"] == wgs_main[
            "complete_higher_flow_and_cut_conclusion"]["strict_phase_lower"],
         "same original first records and true phase lower")
    flow = records(graphs[names[0]]["new_records"][
        "ordinary_flow_orders_2_through_15"], 14, "new flow")
    phase = records(graphs[names[1]]["new_records"][
        "ordinary_phase_orders_2_through_15"], 14, "new phase")
    omega = records(graphs[names[4]]["new_records"][
        "complete_strict_relative_omega_angular_orders_1_through_14"], 14, "new omega")
    binding_fields = (
        "kind", "problem_id", "run_id", "run_attempt", "workflow_event_commit",
        "actual_checkout_commit", "scientific_modules", "manifest_sha256", "runtime",
        "arithmetic_bits", "complete", "proved", "actual_returncode", "stage",
        "failure", "parameters", "retained_scope", "input_sha256",
        "verified_original_inputs", "original_source_AST_evidence",
        "gates", "actual_progress", "saved_record_counts",
        "completed_targets", "current_target", "automatic_retry_authorized")
    return {
        "kind": "complete_same_strict_angular_packet_v1",
        "complete": True,
        "strict_interval": copy.deepcopy(pars["strict_interval"]),
        "ordinary_physical_angle_period": pars["physical_period"],
        "all_shorter_intervals_both_branches_both_orientations":
            scope["all_shorter_both_orientations_both_characteristics_and_drift"],
        "relative_omega_derivatives_are_ordinary": True,
        "flow_orders_1_through_14": records([old["flow_1"]] + flow[:13], 14, "flow packet"),
        "phase_orders_1_through_15": records([old["phase_1"]] + phase, 15, "phase packet"),
        "relative_omega_orders_1_through_14": omega,
        "strict_phase_lower": copy.deepcopy(old["strict_phase_lower"]),
        "complete_source_identity": copy.deepcopy(source_identity),
        "packet_binding": {key: copy.deepcopy(wbf[key]) for key in binding_fields},
        "flow_order_15_is_retained_in_complete_source_not_recomputed": True,
        "WDG_cut_T_high_records_are_a_separate_immutable_input": True}

