def fresh_outputs(out):
    require(not out.exists(), "complete or partial scientific index already exists")
    for spec in SIDECAR_SPECS:
        require(not (out.parent / spec["relative_path"]).exists(),
                "complete or partial natural conclusion already exists")

def atomic_complete(path, value):
    raw = canonical(value)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    try:
        with temporary.open("wb") as handle:
            handle.write(raw)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        directory = os.open(str(path.parent), os.O_RDONLY)
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    finally:
        sys.stdout.write(raw.decode("utf-8"))
        sys.stdout.flush()
    restored_raw = path.read_bytes()
    require(restored_raw == raw, "complete atomic byte readback differs")
    restored = exact_json(restored_raw)
    require(canonical(restored) == raw, "complete canonical readback differs")
    return restored, raw

def bounded_diagnostic(text, maximum_utf8_bytes):
    raw = text.encode("utf-8")
    clipped = raw[:maximum_utf8_bytes].decode("utf-8", "ignore")
    return clipped, clipped.encode("utf-8") != raw

def failure_record(exc):
    trace = traceback.format_exc()
    sys.stderr.write(trace)
    sys.stderr.flush()
    typ, a = bounded_diagnostic(type(exc).__name__, DIAGNOSTIC_TYPE_BYTES)
    msg, b = bounded_diagnostic(str(exc), DIAGNOSTIC_MESSAGE_BYTES)
    tb, c = bounded_diagnostic(trace, DIAGNOSTIC_TRACEBACK_BYTES)
    return {"type": typ, "message": msg, "traceback": tb,
            "text_truncated": bool(a or b or c), "full_text_in_job_log": True}

def record_paths(value, path=None):
    path = [] if path is None else path
    if isinstance(value, dict):
        if set(value) == {"ball"} and isinstance(value["ball"], str):
            return [path]
        answer = []
        for key, item in value.items():
            answer.extend(record_paths(item, path + [key]))
        return answer
    if isinstance(value, list):
        answer = []
        for key, item in enumerate(value):
            answer.extend(record_paths(item, path + [key]))
        return answer
    return []

def complete_shape(value, pattern):
    if pattern == "__NEW_BALL__":
        return (isinstance(value, str) and len(value.encode("ascii")) <= MAX_NEW_BALL_BYTES
                and bool(value) and not any(x in value.lower() for x in ("nan", "inf")))
    if pattern == "__INTEGER_64__":
        return type(value) is int and value >= 0 and len(str(value)) <= 64
    if isinstance(pattern, str) and re.fullmatch("__STRING_[0-9]+__", pattern):
        maximum = int(re.search("[0-9]+", pattern).group())
        return isinstance(value, str) and len(value.encode("utf-8")) <= maximum
    if isinstance(pattern, dict):
        return isinstance(value, dict) and set(value) == set(pattern) and all(
            complete_shape(value[key], item) for key, item in pattern.items())
    if isinstance(pattern, list):
        return isinstance(value, list) and len(value) == len(pattern) and all(
            complete_shape(a, b) for a, b in zip(value, pattern))
    return type(value) is type(pattern) and value == pattern

class ScalarAPI:
    """The sole new arithmetic context. No old mathematical producer is loaded."""
    def __init__(self, arb_type, owner):
        self.arb, self.owner = arb_type, owner
    def ex(self, value):
        value = Fraction(value)
        return self.arb(value.numerator) / self.arb(value.denominator)
    def up(self, value):
        value = self.arb(value)
        require(value.is_finite(), "nonfinite new bound")
        require(value.lower() >= 0, "negative norm majorant")
        return value.upper()
    def lower(self, value, label="positive denominator"):
        value = self.arb(value)
        require(value.is_finite() and value.lower() > 0, label)
        return value.lower()
    def read_up(self, record):
        require(isinstance(record, dict) and set(record) == {"ball"}
                and isinstance(record["ball"], str), "whole upper record")
        return self.up(self.arb(record["ball"]))
    def read_lower(self, record, label="original positive lower"):
        require(isinstance(record, dict) and set(record) == {"ball"}
                and isinstance(record["ball"], str), "whole lower record")
        return self.lower(self.arb(record["ball"]), label)
    def record(self, value):
        # The sink inserts this complete record before any print or further use.
        return {"ball": self.up(value).str(75)}
    def checkpoint_current_node(self, name, doc, progress):
        return self.owner.checkpoint(name, doc, progress)

class AtomicOwner:
    def __init__(self, out, index, work, progress):
        self.out, self.index, self.work, self.progress = out, index, work, progress
        self.completed = {}
        self.clock_started = None
        self.api = None

    def gate(self, name):
        gates = self.index["gates"]
        require(len(gates) < len(GATE_LABELS) and name == GATE_LABELS[len(gates)],
                "complete scientific gate order")
        gates.append({"name": name, "passed": True})

    def publish_index(self, enforce_size=True):
        if self.clock_started is not None:
            elapsed = time.perf_counter() - self.clock_started
            require(math.isfinite(elapsed) and elapsed >= 0, "finite elapsed time")
            self.index["actual_mathematical_wall_seconds"] = elapsed
        restored, raw = atomic_complete(self.out, self.index)
        if enforce_size:
            require(len(raw) <= MAX_INDEX_BYTES, "complete scientific index byte budget")
        require(restored == self.index, "whole index readback")
        return restored

    def binding(self, name):
        direct = {}
        for previous in ORDERED_GRAPH_NAMES[:ORDERED_GRAPH_NAMES.index(name)]:
            receipt = next(item for item in self.index["scientific_graph_files"]
                if item["path"] == "graphs/" + previous + ".json")
            require(previous in self.completed, "complete direct predecessor required")
            direct[previous] = {"file": receipt["path"], "bytes": receipt["bytes"],
                                "sha256": receipt["sha256"]}
        return {
            "run_id": self.index["run_id"], "run_attempt": self.index["run_attempt"],
            "workflow_event_commit": self.index["workflow_event_commit"],
            "actual_checkout_commit": self.index["actual_checkout_commit"],
            "parameters_sha256": digest(canonical(PARAMETERS)),
            "manifest_sha256": self.index["manifest_sha256"],
            "scientific_modules": copy.deepcopy(self.index["scientific_modules"]),
            "input_sha256": {spec["role"]: spec["sha256"] for spec in EXPECTED_OLD_FILES},
            "direct_saved_dependencies": direct}

    def progress_without_document(self, progress):
        return {key: copy.deepcopy(value) for key, value in progress.items()
                if key != "complete_scientific_document_prefix"}

    def validate_prefix(self, name, doc, progress):
        require(name in ORDERED_GRAPH_NAMES
                and self.index["current_target"] == name and name not in self.completed,
                "sole active new natural target")
        require(doc["node_name"] == name
                and doc["kind"] == "complete_strict_per_index_scaled_mixed_profile_node_v1"
                and doc["retained_scope"] == RETAINED_SCOPE,
                "same complete mathematical prefix")
        paths = progress["printed_record_paths"]
        require(isinstance(paths, list)
                and len({canonical(path) for path in paths}) == len(paths)
                and set(map(tuple, paths)) == set(map(tuple, record_paths(doc["new_records"]))),
                "every printed record has one complete path in the sole document")
        require(len(paths) <= GRAPH_NEW_COUNTS[name]
                and scalar_records(doc["copied_original_records"]) <= GRAPH_OLD_COUNTS[name],
                "complete natural target prefix cannot exceed its declared graph")
        for path in paths:
            record = at(doc["new_records"], path)
            require(isinstance(record, dict) and set(record) == {"ball"}
                    and isinstance(record["ball"], str), "whole printed record")
        return len(paths)

    def write_node(self, name, doc, progress, complete, failure=None, enforce_size=True):
        if failure is None:
            count = self.validate_prefix(name, doc, progress)
        else:
            # A qualification failure must not discard the very prefix it diagnoses.
            require(name in ORDERED_GRAPH_NAMES and name not in self.completed,
                    "retain only the active unfinished target")
            count = len(progress.get("printed_record_paths", []))
        conclusion = copy.deepcopy(doc)
        conclusion["complete"] = bool(complete)
        envelope = {
            "kind": "WSM_complete_atomic_node_v1", "node_name": name,
            "complete": bool(complete), "binding": self.binding(name),
            "conclusion": conclusion, "printed_record_event_count": count,
            "all_printed_records_in_complete_conclusion": True,
            "automatic_retry_authorized": False, "failure": copy.deepcopy(failure)}
        if not complete:
            envelope["progress"] = self.progress_without_document(progress)
        relative = "graphs/" + name + ".json"
        saved, raw = atomic_complete(self.out.parent / relative, envelope)
        receipt = {"path": relative, "bytes": len(raw), "sha256": digest(raw)}
        existing = [item for item in self.index["scientific_graph_files"]
                    if item["path"] != relative]
        existing.append(receipt)
        self.index["scientific_graph_files"] = [
            next(item for item in existing if item["path"] == spec["relative_path"])
            for spec in SIDECAR_SPECS
            if any(item["path"] == spec["relative_path"] for item in existing)]
        self.index["saved_record_counts"][name] = count
        self.index["original_record_copy_counts"][name] = scalar_records(
            conclusion["copied_original_records"])
        self.index["actual_progress"]["new_records_saved"] = sum(
            self.index["saved_record_counts"].values())
        self.index["actual_progress"]["original_records_copied_in_graphs"] = sum(
            self.index["original_record_copy_counts"].values())
        self.index["partial_target_reference"] = None if complete else {
            "node_name": name, **receipt,
            "printed_record_paths_reference": ["progress", "printed_record_paths"]}
        self.index["stage"] = ("completed:" if complete else "prefix_saved:") + name
        # Synchronize the index even when a subsequent cap/shape check fails.
        self.publish_index(enforce_size=enforce_size)
        if enforce_size:
            cap = next(spec["maximum_bytes"] for spec in SIDECAR_SPECS
                       if spec["node_name"] == name)
            require(len(raw) <= cap and len(raw) < 100000,
                    "complete natural scientific file byte budget")
            for path in progress["printed_record_paths"]:
                text = at(conclusion["new_records"], path)["ball"]
                require(text.isascii() and len(text.encode("ascii")) <= MAX_NEW_BALL_BYTES,
                        "new record exceeds complete frozen display budget")
        require(saved["conclusion"] == conclusion, "complete saved conclusion readback")
        return saved["conclusion"]

    def checkpoint(self, name, doc, progress):
        return self.write_node(name, doc, progress, False)

    def begin(self, name):
        expected = ORDERED_GRAPH_NAMES[len(self.index["completed_targets"])]
        require(name == expected and self.index["current_target"] is None
                and name not in self.completed, "new natural target order")
        self.index["current_target"] = name
        self.index["stage"] = "started:" + name
        self.progress.clear()
        empty={"kind":"complete_strict_per_index_scaled_mixed_profile_node_v1",
               "node_name":name,"complete":False,
               "basis":self.work["schema"]["complete_shapes"][name]["basis"],
               "new_records":{},"copied_original_records":{},
               "retained_scope":copy.deepcopy(RETAINED_SCOPE)}
        self.progress.update({"node_name":name,"complete":False,
            "complete_scientific_document_prefix":empty,"printed_record_paths":[],
            "each_printed_record_reconstructible_at_its_complete_prefix_path":True,
            "current_stage":"before_private_finite_construction"})
        # Persist even the zero-record target before its first private operation.
        self.checkpoint(name,empty,self.progress)

    def publish_graph(self, name, doc):
        require(doc["complete"] is True, "only complete natural conclusion publication")
        count = self.validate_prefix(name, doc, self.progress)
        require(count == GRAPH_NEW_COUNTS[name]
                and scalar_records(doc["copied_original_records"]) == GRAPH_OLD_COUNTS[name],
                "all complete natural records and original copies")
        pattern = copy.deepcopy(self.work["schema"]["complete_shapes"][name])
        if "angular_predecessor_identity" in pattern:
            pattern["angular_predecessor_identity"] = copy.deepcopy(
                self.work["files"]["sharp_angular"])
        if "relative_angular_predecessor_identity" in pattern:
            pattern["relative_angular_predecessor_identity"] = copy.deepcopy(
                self.work["files"]["relative_angular"])
        if name == "strict_complete_whole_receiver":
            for which in ("whole", "reduced"):
                choice = doc["whole_candidate_choices"][which]
                require(choice["selected_label"] in (
                    "new_complete_strict_per_index_candidate", "prior_complete_WRT_selected"),
                    "one complete same-operator candidate")
                expected_path = choice["new_record_path"] if choice["selected_label"] == (
                    "new_complete_strict_per_index_candidate") else choice["prior_record_path"]
                require(choice["selected_record_path"] == expected_path,
                        "complete selected candidate path")
                new_upper = self.api.read_up(at(doc, choice["new_record_path"]))
                prior_upper = self.api.read_up(at(doc, choice["prior_record_path"]))
                require((choice["selected_label"] == "new_complete_strict_per_index_candidate")
                        == bool(new_upper < prior_upper), "old wins an exact saved-upper tie")
                pattern["whole_candidate_choices"][which]["selected_label"] = choice["selected_label"]
                pattern["whole_candidate_choices"][which]["selected_record_path"] = expected_path
        require(complete_shape(doc, pattern), "entire complete natural scientific shape")
        saved = self.write_node(name, doc, self.progress, True)
        self.completed[name] = saved
        self.index["completed_targets"].append(name)
        self.index["actual_progress"]["new_graphs_completed"] += 1
        self.index["current_target"] = None
        self.index["partial_target_reference"] = None
        self.index["stage"] = "completed:" + name
        self.gate(GATE_LABELS[12 + len(self.completed) - 1])
        self.publish_index()
        return saved

    def preserve_failure(self, exc):
        diagnostic = failure_record(exc)
        self.index["failure"] = diagnostic
        self.index["complete"] = False
        self.index["proved"] = False
        self.index["actual_returncode"] = 1
        name = self.index["current_target"]
        doc = self.progress.get("complete_scientific_document_prefix")
        if name is not None and name not in self.completed and isinstance(doc, dict):
            self.write_node(name, doc, self.progress, False, diagnostic, enforce_size=False)
        self.index["stage"] = "failed"
        self.publish_index(enforce_size=False)

def load_new_module(root, spec):
    path = safe_path(root, spec["path"])
    name = "current_wsm_" + spec["role"]
    module_spec = importlib.util.spec_from_file_location(name, path)
    require(module_spec is not None and module_spec.loader is not None, "new library loader")
    module = importlib.util.module_from_spec(module_spec)
    sys.modules[name] = module
    module_spec.loader.exec_module(module)
    return module

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for key in ("repo", "manifest", "manifest-sha", "out"):
        parser.add_argument("--" + key, required=True)
    parser.add_argument("--bits", type=int, required=True)
    parser.add_argument("--preflight-only", action="store_true")
    args = parser.parse_args()
    require(args.bits == 320, "fixed 320-bit arithmetic")
    require(os.environ.get("GITHUB_ACTIONS") == "true"
            and os.environ.get("GITHUB_REPOSITORY") == PUBLIC_REPOSITORY,
            "public own Actions only")
    run, attempt = os.environ.get("GITHUB_RUN_ID", ""), os.environ.get("GITHUB_RUN_ATTEMPT", "")
    event, checkout = os.environ.get("GITHUB_SHA", ""), os.environ.get("ACTUAL_CHECKOUT_COMMIT", "")
    require(re.fullmatch("[0-9]{1,32}", run) and re.fullmatch("[0-9]{1,8}", attempt)
            and re.fullmatch("[0-9a-f]{40}", event)
            and re.fullmatch("[0-9a-f]{40}", checkout), "actual public run identity")
    out = Path(args.out)
    fresh_outputs(out)
    if args.preflight_only:
        work = read_only_admission(args.repo, args.manifest, args.manifest_sha)
        print(canonical({
            "kind": PREFLIGHT_KIND, "problem_id": PROBLEM_ID, "complete": True,
            "manifest_sha256": args.manifest_sha, "actual_checkout_commit": checkout,
            "scientific_modules": work["module_map"],
            "verified_original_inputs": work["verified"],
            "complete_original_qualification_identities": OLD_QUALIFICATION_IDENTITIES,
            "new_records_not_started": 152, "new_graphs_not_started": 3,
            "old_scientific_calls": 0, "flint_imported": False,
            "scientific_sidecars": SIDECAR_SPECS,
            "whole_twenty_input_readonly_admission": True
        }).decode("utf-8"), end="", flush=True)
        return 0
    index = {
        "kind": KIND, "problem_id": PROBLEM_ID, "complete": False, "proved": False,
        "stage": "read_only_admission", "failure": None, "actual_returncode": None,
        "runtime": {}, "arithmetic_bits": args.bits, "run_id": run, "run_attempt": attempt,
        "workflow_event_commit": event, "actual_checkout_commit": checkout,
        "scientific_modules": {}, "manifest_sha256": args.manifest_sha, "input_sha256": {},
        "verified_original_inputs": [], "original_source_AST_evidence": {},
        "parameters": copy.deepcopy(PARAMETERS), "retained_scope": copy.deepcopy(RETAINED_SCOPE),
        "accepted_old_inputs": {}, "angular_packet_identity": None,
        "relative_angular_packet_identity": None,
        "current_target": None, "completed_targets": [],
        "saved_record_counts": {name: 0 for name in ORDERED_GRAPH_NAMES},
        "original_record_copy_counts": {name: 0 for name in ORDERED_GRAPH_NAMES},
        "scientific_graph_files": [], "partial_target_reference": None,
        "whole_candidate_choices": {}, "gates": [],
        "actual_progress": {"complete_original_files_admitted": 0,
            "new_records_saved": 0, "new_graphs_completed": 0,
            "original_records_copied_in_graphs": 0, "new_whole_comparisons_completed": 0,
            "old_scientific_calls": 0, "old_targets_recomputed": 0,
            "old_producer_imports_or_calls": 0, "history_inputs_restored": 0,
            "new_ray_or_ODE_integrations": 0, "private_mixed_arrays_published": 0},
        "actual_mathematical_wall_seconds": 0.0, "automatic_retry_authorized": False}
    progress = {}
    owner = AtomicOwner(out, index, None, progress)
    owner.publish_index()
    try:
        work = read_only_admission(args.repo, args.manifest, args.manifest_sha)
        owner.work = work
        index["scientific_modules"] = copy.deepcopy(work["module_map"])
        index["input_sha256"] = {item["role"]: item["sha256"] for item in work["verified"]}
        index["input_sha256"]["manifest"] = args.manifest_sha
        index["verified_original_inputs"] = copy.deepcopy(work["verified"])
        index["original_source_AST_evidence"] = copy.deepcopy(work["AST"])
        index["accepted_old_inputs"] = copy.deepcopy(work["accepted"])
        index["angular_packet_identity"] = copy.deepcopy(work["files"]["sharp_angular"])
        index["relative_angular_packet_identity"] = copy.deepcopy(work["files"]["relative_angular"])
        index["gates"] = copy.deepcopy(work["gates"])
        index["actual_progress"]["complete_original_files_admitted"] = 12
        import flint
        from flint import arb, ctx
        ctx.prec = args.bits
        runtime = {"Python": ".".join(map(str, sys.version_info[:3])),
                   "python_flint": flint.__version__}
        require(runtime == {"Python": "3.12.14", "python_flint": "0.9.0"},
                "same reviewed directed runtime")
        index["runtime"] = runtime
        owner.gate(GATE_LABELS[10])
        fresh_graphs = [out.parent / item["relative_path"] for item in SIDECAR_SPECS]
        require(not any(path.exists() for path in fresh_graphs),
                "no complete or partial graph before new arithmetic")
        owner.gate(GATE_LABELS[11])
        support = load_new_module(work["root"], work["files"]["support"])
        finishing = load_new_module(work["root"], work["files"]["finishing"])
        require(list(support.PUBLIC_NODE_ORDER) == ORDERED_GRAPH_NAMES
                and support.complete_scope() == RETAINED_SCOPE
                and support.N0 == 388 and finishing.N0 == 388,
                "new complete same-domain finite libraries")
        api = ScalarAPI(arb, owner)
        owner.api = api
        documents = {key: value for key, value in work["documents"].items()
                     if key not in ("sharp_angular", "relative_angular")}
        owner.clock_started = time.perf_counter()
        owner.begin(ORDERED_GRAPH_NAMES[0])
        session = support.prepare_strict_profile_work(
            documents, work["accepted"], api, progress, work["angular_packet"])
        profile = support.publish_complete_strict_profile(
            session, owner.publish_graph, progress)
        owner.begin(ORDERED_GRAPH_NAMES[1])
        residual = finishing.complete_new_strict_N6(
            session, profile, support, api, owner.publish_graph, progress)
        owner.begin(ORDERED_GRAPH_NAMES[2])
        whole = finishing.complete_new_whole_receiver(
            documents, work["accepted"], profile, residual, support, api,
            owner.publish_graph, progress)
        owner.gate(GATE_LABELS[15])
        require(index["saved_record_counts"] == GRAPH_NEW_COUNTS
                and index["original_record_copy_counts"] == GRAPH_OLD_COUNTS
                and index["actual_progress"]["new_records_saved"] == 152
                and index["actual_progress"]["original_records_copied_in_graphs"] == 39,
                "all 152 new records and 39 exact original copies")
        owner.gate(GATE_LABELS[16])
        index["whole_candidate_choices"] = copy.deepcopy(whole["whole_candidate_choices"])
        index["actual_progress"]["new_whole_comparisons_completed"] = 2
        owner.gate(GATE_LABELS[17])
        for spec in work["verified"]:
            require(check_file(work["root"], spec) == work["raw"][spec["role"]],
                    "complete current input changed during the one child")
        require(Path(args.manifest).read_bytes() == work["manifest_raw"],
                "manifest changed during the one child")
        owner.gate(GATE_LABELS[18])
        require(len(index["scientific_graph_files"]) == 3, "three complete referenced conclusions")
        for reference in index["scientific_graph_files"]:
            raw = (out.parent / reference["path"]).read_bytes()
            require(len(raw) == reference["bytes"] and digest(raw) == reference["sha256"],
                    "whole final referenced graph bytes")
        owner.gate(GATE_LABELS[19])
        require(whole["qualifications"]["old_successful_graphs_and_original_failed_parent_status_preserved"] is True
                and whole["qualifications"]["new_local_mean_jump_positive_root_or_endpoint_targets"] == 0,
                "all unchanged complementary physical terms are retained")
        owner.gate(GATE_LABELS[20])
        index["complete"], index["proved"], index["actual_returncode"] = True, True, 0
        index["stage"], index["current_target"], index["partial_target_reference"] = "complete", None, None
        owner.gate(GATE_LABELS[21])
        owner.publish_index()
        return 0
    except Exception as exc:
        owner.preserve_failure(exc)
        return 1

if __name__ == "__main__":
    sys.exit(main())
